update public.products set description='A mixed selection of turkey portions suitable for soups, stews, grilling, roasting and other dishes that use a combination of poultry cuts.', handling_protocols=array['Treat all portions as raw poultry and keep them cold and separate from ready-to-eat foods.','Do not wash raw turkey; clean hands, utensils and surfaces after handling.','Cook every portion to at least 74°C / 165°F.']::text[], storage_tips=array['If chilled, refrigerate at 4°C or below and use within 1–2 days.','Because the assortment composition is not yet defined, use the conservative frozen quality target of about 3–4 months at -18°C or below.']::text[] where name='Assorted Turkey cuts' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
